#include <iostream>

// Renvoie -1 si piezas est hors de 0..10.
int estimar(int piezas) {
    if (piezas < 0 || piezas > 10) { return -1; }
    if (piezas == 0) { return 0; }
    return 3 + 2 * piezas;
}

int main() {
    int resultado{estimar(12)};
    if (resultado == -1) {
        std::cout << "Commande invalide";
    } else {
        std::cout << resultado;
    }
    return 0;
}

